<!DOCTYPE html><html><head><meta charset="utf-8"><style>@page{margin:30px 36px}body{font-family:DejaVu Sans,sans-serif;color:#13233a;font-size:12px}.head{border-bottom:3px solid #0f766e;padding-bottom:14px}.head h1{font-size:22px;margin:0}.head p{margin:4px 0 0;color:#64748b}.status{float:right;text-transform:uppercase;font-size:10px;font-weight:bold;padding:7px 10px;border-radius:12px;background:#e2e8f0}.pending{color:#b45309}.grid{width:100%;margin-top:24px;border-collapse:collapse}.grid td{padding:10px;border-bottom:1px solid #e2e8f0}.grid td:first-child{color:#64748b;width:34%}.weights{width:100%;margin:22px 0;border-collapse:separate;border-spacing:8px}.weights td{background:#f1f5f9;text-align:center;padding:16px}.weights span{display:block;color:#64748b;font-size:10px;text-transform:uppercase}.weights strong{display:block;font-size:21px;margin:5px}.footer{text-align:center;margin-top:32px;color:#94a3b8;font-size:10px}</style></head><body>
<div class="head"><span class="status {{ $weighment->status==='completed'?'':'pending' }}">{{ str_replace('_',' ',$weighment->status) }}</span><h1>SENTINEL</h1><p>Weighment slip · {{ $weighment->weighment_no }}</p></div>
